const {
  Document, Packer, Paragraph, Table, TableRow, TableCell,
  TextRun, HeadingLevel, AlignmentType, WidthType, BorderStyle,
  ShadingType, TableLayoutType
} = require("docx");
const fs = require("fs");
const XLSX = require("xlsx");

// ── Read data ──
const wb = XLSX.readFile("/workspace/testbed/data/order_summary.xlsx");
const rows = XLSX.utils.sheet_to_json(wb.Sheets["Orders"]);

// ── Compute stats ──
const total = rows.length;
const confirmed = rows.filter(r => r.Status === "confirmed");
const cancelled = rows.filter(r => r.Status === "cancelled");
const confirmedRev = confirmed.reduce((s, r) => s + r["Total Paid"], 0);
const cancelledRev = cancelled.reduce((s, r) => s + r["Total Paid"], 0);
const cancellationRate = ((cancelled.length / total) * 100).toFixed(1);

const customers = new Set(rows.map(r => r.Customer));

// Top customers by confirmed spend
const custSpend = {};
confirmed.forEach(r => {
  const c = r.Customer;
  if (!custSpend[c]) custSpend[c] = { orders: 0, spent: 0 };
  custSpend[c].orders++;
  custSpend[c].spent += r["Total Paid"];
});
const topCustomers = Object.entries(custSpend)
  .sort((a, b) => b[1].spent - a[1].spent)
  .slice(0, 5);

// Product popularity
const prodCount = {};
rows.forEach(r => {
  r.Items.split(",").map(i => i.trim()).forEach(item => {
    prodCount[item] = (prodCount[item] || 0) + 1;
  });
});
const topProducts = Object.entries(prodCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 6);

// ── Helper: build a styled table ──
const HEADER_FILL = "2E74B5";
const ALT_FILL = "F2F2F2";

function headerCell(text, width) {
  return new TableCell({
    width: { size: width, type: WidthType.PERCENTAGE },
    shading: { type: ShadingType.SOLID, color: HEADER_FILL, fill: HEADER_FILL },
    children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text, bold: true, color: "FFFFFF", size: 22, font: "Calibri" })]
    })]
  });
}

function dataCell(text, width, shaded) {
  return new TableCell({
    width: { size: width, type: WidthType.PERCENTAGE },
    shading: shaded ? { type: ShadingType.SOLID, color: ALT_FILL, fill: ALT_FILL } : undefined,
    children: [new Paragraph({
      spacing: { before: 30, after: 30 },
      children: [new TextRun({ text: String(text), size: 21, font: "Calibri" })]
    })]
  });
}

function makeTable(headers, widths, dataRows) {
  const border = { style: BorderStyle.SINGLE, size: 1, color: "BBBBBB" };
  const borders = { top: border, bottom: border, left: border, right: border };
  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    layout: TableLayoutType.FIXED,
    rows: [
      new TableRow({ children: headers.map((h, i) => headerCell(h, widths[i])) }),
      ...dataRows.map((cells, idx) =>
        new TableRow({
          children: cells.map((c, i) => dataCell(c, widths[i], idx % 2 === 1))
        })
      )
    ],
    borders
  });
}

// ── Shortcut helpers ──
function heading(text, level) {
  return new Paragraph({
    heading: level,
    spacing: { before: 280, after: 120 },
    children: [new TextRun({ text, font: "Calibri" })]
  });
}

function body(text) {
  return new Paragraph({
    spacing: { after: 100 },
    children: [new TextRun({ text, size: 22, font: "Calibri" })]
  });
}

function bullet(text) {
  return new Paragraph({
    bullet: { level: 0 },
    spacing: { after: 60 },
    children: [new TextRun({ text, size: 22, font: "Calibri" })]
  });
}

// ── Build document ──
const doc = new Document({
  styles: {
    default: {
      heading1: { run: { size: 36, bold: true, color: "1F4E79", font: "Calibri" } },
      heading2: { run: { size: 28, bold: true, color: "2E74B5", font: "Calibri" } },
    }
  },
  sections: [{
    properties: {
      page: { margin: { top: 1200, bottom: 1200, left: 1200, right: 1200 } }
    },
    children: [
      // Title
      heading("Order Summary Analysis", HeadingLevel.HEADING_1),
      body("Source: order_summary.xlsx"),
      body(""),

      // Overview
      heading("Overview", HeadingLevel.HEADING_2),
      makeTable(
        ["Metric", "Value"],
        [60, 40],
        [
          ["Total Orders", String(total)],
          ["Date Range", "2026-09-02 to 2026-09-04"],
          ["Unique Customers", String(customers.size)],
        ]
      ),
      body(""),

      // Order Status
      heading("Order Status", HeadingLevel.HEADING_2),
      makeTable(
        ["Status", "Count", "Total Revenue"],
        [40, 30, 30],
        [
          ["✅ Confirmed", String(confirmed.length), `$${confirmedRev.toLocaleString()}`],
          ["❌ Cancelled", String(cancelled.length), `$${cancelledRev.toLocaleString()}`],
        ]
      ),
      body(`Cancellation rate: ${cancellationRate}%`),
      body(""),

      // Top Customers
      heading("Top Customers (by Confirmed Spend)", HeadingLevel.HEADING_2),
      makeTable(
        ["Customer", "Confirmed Orders", "Total Paid"],
        [45, 25, 30],
        topCustomers.map(([name, d]) => [name, String(d.orders), `$${d.spent.toLocaleString()}`])
      ),
      body(`Maya Chen is the highest-value customer, accounting for ~${Math.round(topCustomers[0][1].spent / confirmedRev * 100)}% of confirmed revenue.`),
      body(""),

      // Most Popular Products
      heading("Most Popular Products", HeadingLevel.HEADING_2),
      makeTable(
        ["Product", "Times Ordered"],
        [70, 30],
        topProducts.map(([name, count]) => [name, String(count)])
      ),
      body("The LogiTech Wireless Mouse M310 is the best seller, appearing in nearly half of all orders."),
      body(""),

      // Key Takeaways
      heading("Key Takeaways", HeadingLevel.HEADING_2),
      bullet("Revenue concentration — The top 3 named customers (Maya Chen, Evan Parker, Alicia Morgan) drive a significant share of revenue."),
      bullet("Low cancellation rate — Only 3 out of 27 orders were cancelled (all from Maya Chen and Jordan Alvarez on Sep 2)."),
      bullet("Bundling opportunity — The LogiTech Mouse + OXO Mixing Bowl Set combo appears in 6 orders, suggesting a frequent cross-category pairing worth promoting."),
      bullet("All orders are from Sep 2–4, 2026 — This is a very narrow window, likely a snapshot rather than a full historical dataset."),
    ]
  }]
});

// ── Write file ──
Packer.toBuffer(doc).then(buf => {
  const out = "/workspace/data/order_analysis.docx";
  fs.writeFileSync(out, buf);
  console.log("✅ Report saved to", out);
});
